window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8904fb562045ee80"]={"versions": [{"id": "FIG-8904fb562045ee80", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) im Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es spezifiziert die grundlegende hierarchische Strukturierung von REST-Dienstschnittstellen (<code>RestServiceInterface</code>) und deren Zerlegung in Ressourcen und Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metamodell-Klassen:</p>\n<ul class=\"fig-list\"><li><code>RestServiceInterface</code>: Spezialisierung/Art von <code>PortInterface</code>, aggregiert per Komposition über die Rolle <code>+resource</code> mit der Kardinalität <code>1..*</code> Instanzen von <code>RestResourceDef</code>.\n</li><li><code>RestResourceDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert eine REST-Ressourcendefinition. Sie besitzt eine rekursive Komposition auf sich selbst über die Rolle <code>+resource</code> mit Kardinalität <code>0..*</code> zur Abbildung verschachtelter Sub-Ressourcen sowie eine Komposition über die Rolle <code>+element</code> mit Kardinalität <code>1..*</code> auf <code>RestElementDef</code>.\n</li><li><code>RestElementDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert ein untergeordnetes REST-Element innerhalb einer Ressource.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Kompositionen definieren die statische Schachtelungshierarchie eines REST-Service-Interfaces vom Wurzelelement über optionale Unterressourcen bis hin zu den konkreten REST-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell erzwingt für jedes <code>RestServiceInterface</code> das Vorhandensein von mindestens einer Ressource (<code>1..*</code>). Jede Ressource <code>RestResourceDef</code> muss wiederum mindestens ein <code>RestElementDef</code> (<code>1..*</code>) kapseln. Verschachtelungen von Unterressourcen sind optional (<code>0..*</code>). Beide untergeordneten Typen erben von <code>Identifiable</code> und besitzen somit verbindlich die entsprechenden Identifikations- und Namenskonventionen (wie <code>shortName</code>).</p>"}, {"id": "FIG-9611811f59b5c355", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) im Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es spezifiziert die grundlegende hierarchische Strukturierung von REST-Dienstschnittstellen (<code>RestServiceInterface</code>) und deren Zerlegung in Ressourcen und Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metamodell-Klassen:</p>\n<ul class=\"fig-list\"><li><code>RestServiceInterface</code>: Spezialisierung/Art von <code>PortInterface</code>, aggregiert per Komposition über die Rolle <code>+resource</code> mit der Kardinalität <code>0..*</code> Instanzen von <code>RestResourceDef</code>.\n</li><li><code>RestResourceDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert eine REST-Ressourcendefinition. Sie besitzt eine rekursive Komposition auf sich selbst über die Rolle <code>+resource</code> mit Kardinalität <code>0..*</code> zur Abbildung verschachtelter Sub-Ressourcen sowie eine Komposition über die Rolle <code>+element</code> mit Kardinalität <code>1..*</code> auf <code>RestElementDef</code>.\n</li><li><code>RestElementDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert ein untergeordnetes REST-Element innerhalb einer Ressource.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Kompositionen definieren die statische Schachtelungshierarchie eines REST-Service-Interfaces vom Wurzelelement über optionale Unterressourcen bis hin zu den konkreten REST-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>RestServiceInterface</code> kann optional keine, eine oder mehrere Ressourcen besitzen (<code>0..*</code>). Jede definierte <code>RestResourceDef</code> muss mindestens ein <code>RestElementDef</code> (<code>1..*</code>) enthalten. Verschachtelungen von Unterressourcen sind optional (<code>0..*</code>). <code>RestResourceDef</code> und <code>RestElementDef</code> erben von <code>Identifiable</code> und unterliegen damit den standardisierten Identifikations- und Benennungsregeln (z. B. <code>shortName</code>).</p>"}, {"id": "FIG-033568b9fe161a26", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) im Kontext der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es spezifiziert die grundlegende hierarchische Strukturierung von REST-Dienstschnittstellen (<code>RestServiceInterface</code>) und deren Zerlegung in Ressourcen und Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metamodell-Klassen:</p>\n<ul class=\"fig-list\"><li><code>RestServiceInterface</code>: Spezialisierung/Art von <code>PortInterface</code>, aggregiert per Komposition über die Rolle <code>+resource</code> mit der Kardinalität <code>0..*</code> Instanzen von <code>RestResourceDef</code>.\n</li><li><code>RestResourceDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert eine REST-Ressourcendefinition. Sie besitzt eine rekursive Komposition auf sich selbst über die Rolle <code>+resource</code> mit Kardinalität <code>0..*</code> zur Abbildung verschachtelter Sub-Ressourcen sowie eine Komposition über die Rolle <code>+element</code> mit Kardinalität <code>1..*</code> auf <code>RestElementDef</code>.\n</li><li><code>RestElementDef</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert ein untergeordnetes REST-Element innerhalb einer Ressource.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Kompositionen definieren die statische Schachtelungshierarchie eines REST-Service-Interfaces vom Wurzelelement über optionale Unterressourcen bis hin zu den konkreten REST-Elementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>RestServiceInterface</code> kann optional keine, eine oder mehrere Ressourcen besitzen (<code>0..*</code>). Jede definierte <code>RestResourceDef</code> muss mindestens ein <code>RestElementDef</code> (<code>1..*</code>) enthalten. Verschachtelungen von Unterressourcen sind optional (<code>0..*</code>). <code>RestResourceDef</code> und <code>RestElementDef</code> erben von <code>Identifiable</code> und unterliegen damit den standardisierten Identifikations- und Benennungsregeln (z. B. <code>shortName</code>).</p>"}], "trans": [{"from": "FIG-8904fb562045ee80", "to": "FIG-9611811f59b5c355", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kardinalität der Komposition von <code>RestServiceInterface</code> zu <code>RestResourceDef</code> (<code>+resource</code>): Geändert von <code>1..*</code> auf <code>0..*</code>.\n</li></ul>"}, {"from": "FIG-9611811f59b5c355", "to": "FIG-033568b9fe161a26", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
